source = '''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    best = None
    for color in set(v for row in grid for v in row if v != bg):
        for top in range(h - 2):
            for bottom in range(top + 2, h):
                for left in range(w - 2):
                    for right in range(left + 2, w):
                        if (all(grid[top][c] == color and grid[bottom][c] == color for c in range(left, right + 1))
                            and all(grid[r][left] == color and grid[r][right] == color for r in range(top, bottom + 1))):
                            area = (bottom - top - 1) * (right - left - 1)
                            if best is None or area > best[0]:
                                best = (area, top, bottom, left, right)
    result = [row[:] for row in grid]
    if best is not None:
        _, top, bottom, left, right = best
        for r in range(top + 1, bottom):
            for c in range(left + 1, right):
                result[r][c] = 4
    return result
'''
